import React, { useState, useEffect } from "react";
import { Calendar, Badge, Modal, notification, List, Button } from "antd";
import "./MeetingRoomCalendar.css";
import dayjs from "dayjs";
// import EditBookingModal from "./EditBookingModal";
// import BookingRoomModal from "./BookingRoomModal";

function MeetingRoomCalendarModal({ open, bookedList, onClose }) {
  // const [bookings, setBookings] = useState([]);
  const [selectedDateBookings, setSelectedDateBookings] = useState([]);
  const [isModalVisible, setIsModalVisible] = useState(false);

  // const [loading, setLoading] = useState(false);

  // Function to get event data for a specific date
  const getListData = (value) => {
    const dateString = value.format("YYYY-MM-DD");
    return bookedList.filter(
      (booking) => dayjs(booking.date).format("YYYY-MM-DD") === dateString
    );
  };

  // Custom cell rendering for the calendar
  const dateCellRender = (value) => {
    const listData = getListData(value);
    return (
      <ul className="events">
        {/* <div style={{ display: "flex", justifyContent: "center" }}>
          <Badge count={listData.length} />
        </div> */}
        {listData.map((item) => (
          <Badge
            status="error"
            text={
              <span style={{ fontSize: "14px" }}>
                {dayjs(item.start_time, "HH:mm:ss").format("HH:mm")}-
                {dayjs(item.end_time, "HH:mm:ss").format("HH:mm")}
              </span>
            }
          />
        ))}
      </ul>
    );
  };

  const handleClose = () => {
    onClose(false);
  };

  // Handle click on a date in the calendar (optional: if you want a separate modal for daily view)
  const onSelectDate = (value) => {
    const bookingsOnSelectedDate = getListData(value);
    setSelectedDateBookings(bookingsOnSelectedDate);
    if (bookingsOnSelectedDate.length > 0) {
      setIsModalVisible(true);
    } else {
      notification.info({
        message: "ไม่มีการจอง",
        description: `ไม่มีการจองสำหรับวันที่ ${value.format("YYYY-MM-DD")}`,
        placement: "bottomRight",
      });
    }
  };

  const handleModalClose = () => {
    setIsModalVisible(false);
    setSelectedDateBookings([]); // Clear selected bookings
  };

  return (
    <>
      <Modal
        title={`คิวที่จองแล้วตามวันและเวลา`}
        open={open}
        // okButtonProps={{ style: { display: "none" } }} // <--- เพิ่มบรรทัดนี้เพื่อซ่อนปุ่ม OK
        onCancel={handleClose}
        // cancelText="ปิดหน้าต่าง"
        onOk={handleClose}
        okText="ปิดหน้าต่าง"
        cancelButtonProps={{ style: { display: "none" } }}
        destroyOnClose={false} // ตั้งเป็น false เพื่อให้ useEffect จัดการ resetFields
        width="100%"
      >
        <Calendar dateCellRender={dateCellRender} onSelect={onSelectDate} />
      </Modal>

      <Modal
        centered
        title={`การจองสำหรับวันที่ ${
          selectedDateBookings.length > 0
            ? dayjs(selectedDateBookings[0].date).format("YYYY-MM-DD")
            : ""
        }`}
        visible={isModalVisible}
        onCancel={handleModalClose}
        footer={[
          <Button key="back" onClick={handleModalClose}>
            ปิด
          </Button>,
        ]}
      >
        <List
          itemLayout="horizontal"
          dataSource={selectedDateBookings}
          renderItem={(item) => (
            <List.Item>
              <List.Item.Meta
                title={`${item.title} - ${dayjs(
                  item.start_time,
                  "HH:mm:ss"
                ).format("HH:mm")}-${dayjs(item.end_time, "HH:mm:ss").format(
                  "HH:mm"
                )}`}
                description={
                  <>
                    <p>
                      ผู้จอง: {item.booked_by}
                      {/* (โทร: {item.phone}) */}
                    </p>
                    {/* <p>อีเมล: {item.email}</p> */}
                    <p>จำนวนผู้เข้าร่วม: {item.number_attendees} คน</p>
                    {/* <p>ราคา: {item.price} บาท/ชั่วโมง</p> */}
                  </>
                }
              />
            </List.Item>
          )}
        />
      </Modal>
    </>
  );
}

export default MeetingRoomCalendarModal;
