import React, { useEffect, useState } from "react";
import { Card, Button, Row, Col, Typography, Space } from "antd";
import { useNavigate } from "react-router-dom"; // Import useNavigate
import "./BookingPage.css";
import BookingRoomModal from "./BookingRoomModal"; // ตรวจสอบ path
import baseAPI from "../api/baseAPI"; // ตรวจสอบ path
import dayjs from "dayjs"; // ยังไม่ได้ใช้งานในส่วนนี้ แต่มีอยู่แล้ว
import SimpleLoading from "./SimpleLoading"; // ตรวจสอบ path
import { useDispatch } from "react-redux";
import { addAmenity, addFoodAndDrinks } from "../redux/reduxSlice";
import { currencyFormat } from "./utils/Utils";

const { Text, Link } = Typography;

export default function BookingPage() {
  // const [isModalOpen, setIsModalOpen] = useState(false);
  // const [selectedRoom, setSelectedRoom] = useState(null); // ยังคงมีไว้เผื่อคุณจะกลับมาใช้ modal booking

  const [loading, setLoading] = useState(false);
  const [rooms, setRooms] = useState([]);
  const [filteredRooms, setFilteredRooms] = useState([]); // เพิ่ม state สำหรับเก็บห้องที่ถูกกรอง
  const [selectedSize, setSelectedSize] = useState("All"); // เพิ่ม state สำหรับเก็บขนาดที่เลือก (เริ่มต้นที่ 'All')
  const navigate = useNavigate();
  // const [allAmenitiesData, setAllAmenitiesData] = useState([]);
  // const [foodAndDrinksList, setFoodAndDrinksList] = useState([]);

  const dispatch = useDispatch();

  useEffect(() => {
    // เมื่อ rooms หรือ selectedSize เปลี่ยน ให้ทำการกรองข้อมูลใหม่
    if (selectedSize === "All") {
      setFilteredRooms(rooms);
    } else {
      setFilteredRooms(rooms.filter((room) => room.size === selectedSize));
    }
  }, [rooms, selectedSize]); // Dependency array: ทำงานเมื่อ rooms หรือ selectedSize เปลี่ยน

  // เรียกใช้ใน useEffect หรือเมื่อโหลดหน้า
  useEffect(() => {
    fetchAllInitialData();
  }, []);

  const fetchAllInitialData = async () => {
    setLoading(true);
    try {
      const [meetingRooms, amenities, foodAndDrinks] = await Promise.all([
        baseAPI.get(`/meetingrooms`),
        baseAPI.get(`/amenities`),
        baseAPI.get(`/food-drinks/booking`),
      ]);

      // Set หรือ dispatch ข้อมูลที่ได้
      setRooms(meetingRooms.data);
      dispatch(addAmenity(amenities.data));
      dispatch(addFoodAndDrinks(foodAndDrinks.data));

      console.log("อาหารและเครื่องดื่ม", foodAndDrinks.data);
    } catch (error) {
      console.error("เกิดข้อผิดพลาดขณะดึงข้อมูล:", error);
      // อาจแสดง Notification หรือแจ้งเตือนอื่น ๆ ได้ที่นี่
    } finally {
      setLoading(false);
    }
  };

  const handleCardClick = (room) => {
    // นี่คือฟังก์ชันที่เคยพาไปหน้า Details
    navigate(`/meetingrooms/${room.id}`);
  };

  // ฟังก์ชันสำหรับจัดการการคลิกปุ่มกรองขนาดห้อง
  const handleSizeFilter = (size) => {
    setSelectedSize(size);
  };

  return (
    <div className="booking-container">
      <h1 className="booking-header">TEN X จองห้องประชุม / ห้องทำงาน</h1>

      {/* Button Group สำหรับเลือกขนาดห้องประชุม */}
      <div style={{ marginBottom: "20px", textAlign: "center" }}>
        <Space size="middle" wrap>
          <Button
            type={selectedSize === "All" ? "primary" : "default"}
            onClick={() => handleSizeFilter("All")}
          >
            ทั้งหมด (All)
          </Button>
          <Button
            type={selectedSize === "Small" ? "primary" : "default"}
            onClick={() => handleSizeFilter("Small")}
          >
            ขนาดเล็ก (Small)
          </Button>
          <Button
            type={selectedSize === "Medium" ? "primary" : "default"}
            onClick={() => handleSizeFilter("Medium")}
          >
            ขนาดกลาง (Medium)
          </Button>
          <Button
            type={selectedSize === "Large" ? "primary" : "default"}
            onClick={() => handleSizeFilter("Large")}
          >
            ขนาดใหญ่ (Large)
          </Button>
        </Space>
      </div>

      {loading ? (
        <SimpleLoading tip="กำลังโหลดข้อมูล..." />
      ) : (
        <Row gutter={[24, 24]} justify="center">
          {filteredRooms.map(
            (
              room // เปลี่ยนมา map จาก filteredRooms
            ) => (
              <Col xs={24} sm={24} md={12} xl={8} key={room.id}>
                {" "}
                {/* ใช้ room.id เป็น key */}
                <Card
                  title={room.title}
                  variant={true}
                  className="booking-card"
                  // เพิ่ม onClick ที่ Card เพื่อให้คลิกที่ Card แล้วไปหน้า Details
                  onClick={() => handleCardClick(room)}
                  actions={[
                    <a
                      href="tel:0869966998"
                      key="tel"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <Link strong key="tel">
                        โทรจอง 086-996-6998
                      </Link>
                    </a>,
                    <a
                      href="https://lin.ee/znZ8VY0"
                      key="details"
                      // onClick={() => handleCardClick(room)}
                      onClick={(e) => e.stopPropagation()}
                    >
                      <Link strong>LINE Official </Link>
                    </a>,
                  ]}
                  cover={
                    <img
                      alt="cover"
                      src={room.cover}
                      className="card-cover-image"
                    />
                  }
                >
                  <Space direction="vertical" style={{ width: "100%" }}>
                    <Text strong>
                      {currencyFormat(room.price)} บาท/{room.hours} ชั่วโมง
                    </Text>
                    <Text strong>รองรับ: {room.capacity} ที่นั่ง</Text>
                    <Text>{room.description}</Text>
                    <Text type="secondary">
                      โปรโมชั่น: {room.service || "-"}
                    </Text>
                  </Space>

                  {/* <p style={{ marginTop: "16px" }}>
                    <strong>THB{room.price} /ชั่วโมง</strong>
                  </p> */}
                  {/* <Button
                    style={{ marginTop: "16px" }}
                    type="primary"
                    onClick={() => handleCardClick(room)} // คลิ๊กปุ่ม "รายละเอียด" เพื่อไปหน้า Details
                  >
                    รายละเอียด
                  </Button> */}
                </Card>
              </Col>
            )
          )}
          {/* กรณีไม่มีห้องที่กรองได้ */}
          {filteredRooms.length === 0 && !loading && (
            <Col span={24} style={{ textAlign: "center", marginTop: "50px" }}>
              <Text type="secondary">ไม่พบห้องประชุมสำหรับประเภทที่เลือก</Text>
            </Col>
          )}
        </Row>
      )}

      {/* ถ้าคุณยังต้องการใช้ BookingRoomModal ให้คงไว้ */}
      {/* <BookingRoomModal
        open={isModalOpen}
        onClose={setIsModalOpen}
        room={selectedRoom}
        onFinish={handleFinishBook}
      /> */}
    </div>
  );
}
