import React from "react";
import { Spin } from "antd";
import { LoadingOutlined } from "@ant-design/icons"; // ไอคอนสำหรับ Spin แบบกำหนดเอง

const SimpleLoading = ({ tip = "Loading..." }) => {
  // กำหนดไอคอน custom สำหรับ Spin
  const antIcon = <LoadingOutlined style={{ fontSize: 24 }} spin />;

  return (
    <div
      style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        height: "100%", // ทำให้ครอบคลุมพื้นที่ที่ต้องการ
        minHeight: "200px", // กำหนดความสูงขั้นต่ำ
        flexDirection: "column",
      }}
    >
      <Spin indicator={antIcon} size="large" tip={tip} />
      {/*
        Spin component props:
        - size: 'small', 'default', 'large'
        - indicator: กำหนด custom icon (ต้องใช้ @ant-design/icons)
        - tip: ข้อความที่จะแสดงข้างใต้ Spin
      */}
      <p style={{ marginTop: "10px", color: "#999" }}>กำลังโหลดข้อมูล...</p>
    </div>
  );
};

export default SimpleLoading;
