// BookedDataPage.jsx
import React from "react";
import { useSelector } from "react-redux";
import { Card, Typography, Divider, Row, Col, Table, Space } from "antd";
import dayjs from "dayjs";
import "dayjs/locale/th";
import buddhistEra from "dayjs/plugin/buddhistEra";

import { useLocation } from "react-router-dom";
import qrpayment from "../assets/QRTENX.png"; // ต้องมีไฟล์นี้ใน path
import qrline from "../assets/LINE_TENX.png";
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
import { Quotation } from "./pdf/Quotation"; // ต้องมีไฟล์นี้ใน path
pdfMake.vfs = pdfFonts.pdfMake.vfs;

// ต้องระบุตามชื่อของ ไฟล์ font
pdfMake.fonts = {
  THSarabunNew: {
    normal: "THSarabunNew.ttf",
    bold: "THSarabunNew Bold.ttf",
    italics: "THSarabunNew Italic.ttf",
    bolditalics: "THSarabunNew BoldItalic.ttf",
  },
  AngsanaNew: {
    normal: "AngsanaNew.ttf",
    bold: "AngsanaNew Bold.ttf",
    italics: "AngsanaNew Italic.ttf",
    bolditalics: "AngsanaNew Bold Italic.ttf",
  },
  Roboto: {
    normal: "Roboto-Regular.ttf",
    bold: "Roboto-Medium.ttf",
    italics: "Roboto-Italic.ttf",
    bolditalics: "Roboto-MediumItalic.ttf",
  },
};

const { Title, Text, Link } = Typography;

// Utility function (เหมือนเดิม)
const currencyFormat = (num) => {
  return num !== null && num !== undefined
    ? parseFloat(num).toLocaleString("th-TH", {
        minimumFractionDigits: 0,
        maximumFractionDigits: 2,
      })
    : "0";
};

// 1. ⚙️ ฟังก์ชันคำนวณราคารวมค่าเช่าห้องประชุม (Room Rental Cost)
// นำตรรกะมาจาก BookingRoomModal
const calculateTotalPrice = (room, bookingHours) => {
  if (!room || !room.price || !room.hours || !room.next_hour_price) {
    return 0;
  }

  const basePrice = parseFloat(room.price); // ราคาพื้นฐาน
  const baseHours = parseInt(room.hours); // ชั่วโมงพื้นฐาน
  const nextHourPrice = parseFloat(room.next_hour_price); // ราคาต่อชั่วโมงถัดไป

  if (bookingHours <= 0 || isNaN(bookingHours)) {
    return 0;
  }

  if (bookingHours <= baseHours) {
    return basePrice;
  }

  const extraHours = bookingHours - baseHours;
  const extraPrice = extraHours * nextHourPrice;

  const totalPrice = basePrice + extraPrice;

  return parseFloat(totalPrice.toFixed(2));
};

// 2. 💰 แก้ไข Logic การคำนวณหลัก
const calculateBookingDetails = (data) => {
  const dateStr = dayjs(data.date).format("YYYY-MM-DD");
  let start = dayjs(`${dateStr} ${data.start_time}`);
  let end = dayjs(`${dateStr} ${data.end_time}`);

  // แก้ไข: ในข้อมูลที่ Submit มาจาก form (data) ควรมี field เหล่านี้:
  // price, hours, next_hour_price, title
  const roomConfig = {
    price: data.price, // ราคาต่อชั่วโมง/ราคาฐาน
    hours: data.hours || 1, // จำนวนชั่วโมงที่รวมอยู่ในราคาฐาน (สมมติว่ามี field 'hours' ติดมาด้วย)
    next_hour_price: data.next_hour_price || data.price, // ราคาต่อชั่วโมงถัดไป
  };

  if (end.isBefore(start)) end = end.add(1, "day");
  let hoursBooked = end.diff(start, "hour", true);
  if (hoursBooked === 9) hoursBooked = 8;

  // *** 🛠️ ใช้ฟังก์ชัน calculateTotalPrice ที่เรานำเข้ามา ***
  const roomCost = calculateTotalPrice(roomConfig, hoursBooked);

  // const amenitiesCost = data.amenities.reduce(
  //   (sum, item) =>
  //     sum + (Number(item.price) || 0) + (Number(item.deposit) || 0),
  //   0
  // );

  const amenitiesCost = data.amenities.reduce(
    (sum, item) => sum + (Number(item.price) || 0),
    0
  );

  const foodCost = data.food_and_drinks.reduce(
    // foodCost คือรวมราคาอาหารต่อคน * จำนวนคน
    (sum, item) =>
      sum + (Number(item.price) || 0) * (Number(data.number_attendees) || 0),
    0
  );

  const subTotalCost = roomCost + amenitiesCost + foodCost;

  const discountPercentage = Number(data.discount) ?? 0;
  const discountAmount = subTotalCost * (discountPercentage / 100);

  const finalTotalCost = subTotalCost - discountAmount;

  return {
    hoursBooked,
    roomCost, // ค่านี้ถูกต้องตามตรรกะใหม่
    amenitiesCost,
    foodCost,
    subTotalCost,
    discountPercentage,
    discountAmount,
    finalTotalCost,
  };
};

const BookedDataPage = () => {
  const location = useLocation();
  dayjs.locale("th");
  dayjs.extend(buddhistEra); // เพิ่ม plugin สำหรับพุทธศักราช หากต้องการแสดงผล

  const data = location.state?.bookingDetails;
  // console.log("DETAIL", data);

  if (!data) {
    return (
      <Card style={{ maxWidth: 800, margin: "20px auto", textAlign: "center" }}>
        <Title level={4} type="danger">
          ไม่พบข้อมูลการจองล่าสุด
        </Title>
        <Text>กรุณาทำการจองห้องประชุมก่อน</Text>
      </Card>
    );
  }

  // --- Start Rendering with fetched data ---
  const {
    hoursBooked,
    roomCost,
    amenitiesCost,
    foodCost,
    subTotalCost,
    discountPercentage,
    discountAmount,
    finalTotalCost,
  } = calculateBookingDetails(data);

  // สร้าง array รายละเอียดค่าใช้จ่ายสำหรับ Table
  const detailData = [];

  // 3. 📝 แก้ไขรายละเอียดใน Table ให้แสดงราคาต่อชั่วโมงพื้นฐานอย่างถูกต้อง
  const roomPriceBase = Number(data.price || 0);
  const roomBaseHours = Number(data.hours || 1);
  const roomNextHourPrice = Number(data.next_hour_price || roomPriceBase);

  detailData.push({
    key: "room",
    description: `ค่าห้องประชุม (ราคาฐาน ${currencyFormat(
      roomPriceBase
    )} บาท สำหรับ ${roomBaseHours} ชม. / ชม. ถัดไป ${currencyFormat(
      roomNextHourPrice
    )} บาท)`,
    quantity: `${hoursBooked.toFixed(2)} ชั่วโมง`,
    price: roomCost,
  });

  data.amenities.forEach((a, index) => {
    detailData.push({
      key: `amenity-${index}`,
      description: `สิ่งอำนวยความสะดวก: ${a.name}`,
      quantity: "-",
      // price: (Number(a.price) || 0) + (Number(a.deposit) || 0),
      price: Number(a.price) || 0,
      isSubItem: true,
    });
  });

  data.food_and_drinks.forEach((f, index) => {
    detailData.push({
      key: `food-${index}`,
      description: `อาหาร/เครื่องดื่ม: ${f.name} (ต่อชุด ${currencyFormat(
        f.price
      )})`,
      quantity: `${data.number_attendees} ชุด`,
      price: (Number(f.price) || 0) * (Number(data.number_attendees) || 0),
      isSubItem: true,
    });
  });

  const handleDownloadPDF = () => {
    onDownloadPDF(data);
  };

  const onDownloadPDF = async (data) => {
    if (data) {
      const docDefinition = await Quotation(data);
      pdfMake.createPdf(docDefinition).open();
    }
  };

  const columns = [
    {
      title: "รายละเอียด",
      dataIndex: "description",
      key: "description",
    },
    {
      title: "จำนวน",
      dataIndex: "quantity",
      key: "quantity",
      width: 150,
    },
    {
      title: "ราคา (บาท)",
      dataIndex: "price",
      key: "price",
      width: 150,
      align: "right",
      render: (price) => currencyFormat(price),
    },
  ];

  return (
    <div
      style={{ padding: 24, backgroundColor: "#f0f2f5", minHeight: "100vh" }}
    >
      <Card
        title={
          <Title level={3} style={{ textAlign: "center", marginBottom: 0 }}>
            ใบจองห้องประชุม TEN X
          </Title>
        }
        style={{ maxWidth: 800, margin: "0 auto" }}
      >
        <Divider style={{ marginTop: 0, marginBottom: 20 }} />
        {/* --- Customer and Booking Info --- */}
        <Row gutter={[16, 8]} style={{ marginBottom: 16 }}>
          <Col span={12}>
            <Text strong>ชื่อผู้จอง:</Text> {data.booked_by}
          </Col>
          <Col span={12}>
            <Text strong>ห้องประชุม:</Text> {data.title}
          </Col>
          <Col span={12}>
            <Text strong>เบอร์โทร:</Text> {data.phone}
          </Col>
          <Col span={12}>
            <Text strong>วันที่จอง:</Text>{" "}
            {dayjs(data.date).format("DD MMMM YYYY")}
          </Col>
          <Col span={24}>
            <Text strong>เวลา:</Text> {data.start_time.substring(0, 5)} -{" "}
            {data.end_time.substring(0, 5)}
            <Text type="secondary" style={{ marginLeft: 8 }}>
              ({hoursBooked.toFixed(2)} ชั่วโมง)
            </Text>
          </Col>
          <Col span={24}>
            <Text strong>จำนวนผู้เข้าร่วม:</Text> {data.number_attendees} ท่าน
          </Col>
        </Row>
        <div style={{ alignItems: "center", display: "felx" }}>
          <Text type="secondary" italic>
            หมายเหตุ: กรุณาแคปหน้าจอส่วนนี้
            เพื่อนำไปแสดงกับพนักงานในวันที่เข้าใช้ห้องประชุม
          </Text>
        </div>
        <Link
          style={{ display: "flex", justifyContent: "flex-end" }}
          strong
          onClick={handleDownloadPDF}
        >
          ดาวน์โหลด PDF
        </Link>
        <Divider />
        {/* --- Price Details Table --- */}
        <Title level={4}>รายละเอียดค่าใช้จ่าย</Title>{" "}
        <Table
          columns={columns}
          dataSource={detailData}
          pagination={false}
          size="small"
          rowKey="key"
          bordered
          scroll={{ x: "max-content" }}
        />
        {/* --- Summary Table --- */}
        <div style={{ marginTop: 20, textAlign: "right" }}>
          <Row justify="end" gutter={[16, 8]}>
            <Col span={12}>
              <Text strong>รวมยอดก่อนหักส่วนลด:</Text>
            </Col>
            <Col span={6} style={{ textAlign: "right" }}>
              <Text strong>THB {currencyFormat(subTotalCost)}</Text>
            </Col>
          </Row>

          <Row justify="end" gutter={[16, 8]}>
            <Col span={12}>
              <Text strong>ส่วนลด ({discountPercentage || 0}%):</Text>
            </Col>
            <Col span={6} style={{ textAlign: "right" }}>
              <Text strong type="danger">
                - THB {currencyFormat(discountAmount || 0)}
              </Text>
            </Col>
          </Row>

          <Row justify="end" gutter={[16, 8]}>
            <Col span={12}>
              <Title level={5}>ยอดรวมสุทธิ:</Title>
            </Col>
            <Col span={6} style={{ textAlign: "right" }}>
              <Title level={5} type="success">
                THB {currencyFormat(finalTotalCost)}
              </Title>
            </Col>
          </Row>

          <Row justify="end" gutter={[16, 8]}>
            <Col span={12}>
              <Text strong>ชำระค่ามัดจำ :</Text>
            </Col>
            <Col span={6} style={{ textAlign: "right" }}>
              <Text strong type="danger">
                THB {currencyFormat(finalTotalCost > 800 ? "500" : "200")}
              </Text>
            </Col>
          </Row>
        </div>
        <Divider style={{ margin: "8px 0" }} />
        {/* <Text type="danger">
          กรณียอดจองเกิน 1,000 บาท ให้โอนเฉพาะค่ามัดจำจำนวน 500 บาท
          และส่วนที่เหลือชำระในวันที่เข้าใช้ห้องประชุม
        </Text> */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
          }}
        >
          <Title level={5}></Title>
          <Title level={5}>ช่องทางชำระ (ชำระค่ามัดจำ)</Title>

          <img width={200} src={qrpayment} alt="qrpayment" />
          <Text>
            ส่งหลักฐานการชำระ{" "}
            <a
              href="https://lin.ee/znZ8VY0"
              key="details"
              onClick={(e) => e.stopPropagation()}
            >
              <Link strong>คลิกที่นี่</Link>
            </a>{" "}
          </Text>
          <Text> หรือแสกน QRCode Add Line</Text>

          <img width={200} src={qrline} alt="qrline" />
        </div>
      </Card>
    </div>
  );
};

export default BookedDataPage;
