import React from "react";
import dayjs from "dayjs";
import { currencyFormat } from "../utils/Utils"; // ต้องแน่ใจว่า currencyFormat ถูก export จาก Utils

// 1. ⚙️ ฟังก์ชันคำนวณราคารวมค่าเช่าห้องประชุม (Room Rental Cost)
// นำตรรกะมาจาก BookingRoomModal เพื่อความสอดคล้อง
const calculateTotalPrice = (data, bookingHours) => {
  // กำหนดค่าเริ่มต้นให้กับ field ที่อาจไม่มีใน data (สมมติว่ามีการส่ง price, hours, next_hour_price มา)
  const roomConfig = {
    price: Number(data?.price || 0),
    hours: Number(data?.hours || 1), // จำนวนชั่วโมงที่รวมในราคาฐาน (สมมติ 1 ชม. ถ้าไม่มี)
    next_hour_price: Number(data?.next_hour_price || data?.price || 0), // ราคาต่อชั่วโมงถัดไป
  };

  const basePrice = roomConfig.price; // ราคาพื้นฐาน
  const baseHours = roomConfig.hours; // ชั่วโมงพื้นฐาน
  const nextHourPrice = roomConfig.next_hour_price; // ราคาต่อชั่วโมงถัดไป

  if (bookingHours <= 0 || isNaN(bookingHours)) {
    return 0;
  }

  if (bookingHours <= baseHours) {
    return parseFloat(basePrice.toFixed(2));
  }

  // คำนวณชั่วโมงส่วนเกินและราคา
  const extraHours = bookingHours - baseHours;
  const extraPrice = extraHours * nextHourPrice;

  const totalPrice = basePrice + extraPrice;

  return parseFloat(totalPrice.toFixed(2));
};

export const Quotation = async (data) => {
  const dateStr = dayjs(data.date).format("YYYY-MM-DD");
  const start = dayjs(`${dateStr} ${data?.start_time}`);
  let end = dayjs(`${dateStr} ${data?.end_time}`);
  if (end.isBefore(start)) end = end.add(1, "day");
  let hoursBooked = end.diff(start, "hour", true);
  if (hoursBooked === 9) hoursBooked = 8;

  // 2. 💸 ใช้ฟังก์ชันใหม่ในการคำนวณค่าห้อง
  const roomCost = calculateTotalPrice(data, hoursBooked);

  // const amenitiesCost = data?.amenities.reduce(
  //   (sum, item) => sum + (Number(item.price || 0) + Number(item.deposit || 0)),
  //   0
  // );
  const deposit = data.size === "Small" ? 200 : 500;

  const amenitiesCost = data?.amenities.reduce(
    (sum, item) => sum + Number(item.price || 0),
    0
  );

  const foodCost = data?.food_and_drinks.reduce(
    (sum, item) =>
      sum + Number(item.price || 0) * Number(data?.number_attendees || 0),
    0
  );

  const totalCost = roomCost + amenitiesCost + foodCost;

  // Assume data?.discount is a number (e.g., 20 for 20%)
  const discountPercentage = Number(data?.discount || 0);
  const discountAmount = totalCost * (discountPercentage / 100);
  const finalTotalCost = totalCost - discountAmount;

  // กำหนดรายละเอียดราคาสำหรับแสดงในตาราง (เพื่อให้สอดคล้องกับหน้าเว็บ)
  const roomPriceBase = Number(data?.price || 0);
  const roomBaseHours = Number(data?.hours || 1);
  const roomNextHourPrice = Number(data?.next_hour_price || roomPriceBase);

  const docDefinition = {
    content: [
      {
        text: "ใบจองห้องประชุม TEN X",
        style: "header",
        alignment: "center",
        margin: [0, 0, 0, 20],
      },
      { text: `ชื่อผู้จอง: ${data?.booked_by}`, margin: [0, 0, 0, 4] },
      { text: `ห้องประชุม: ${data?.title}`, margin: [0, 0, 0, 4] },
      { text: `วันที่จอง: ${dayjs(data?.date).format("DD/MM/YYYY")}` },
      {
        text: `เวลา: ${data?.start_time?.substring(
          0,
          5
        )} - ${data?.end_time?.substring(0, 5)} (${hoursBooked.toFixed(
          2
        )} ชั่วโมง)`,
      },
      { text: `เบอร์โทร: ${data?.phone}`, margin: [0, 0, 0, 10] },

      {
        table: {
          widths: ["*", "auto", "auto"],
          body: [
            [
              { text: "รายละเอียด", bold: true },
              { text: "จำนวน", bold: true },
              { text: "ราคา (บาท)", bold: true, alignment: "right" },
            ],

            // 3. 📝 ปรับรายละเอียดค่าห้องในตาราง PDF
            [
              `ค่าห้องประชุม (ราคาฐาน ${currencyFormat(
                roomPriceBase
              )} บาท สำหรับ ${roomBaseHours} ชม. / ชม. ถัดไป ${currencyFormat(
                roomNextHourPrice
              )} บาท)`,
              `${hoursBooked.toFixed(2)} ชั่วโมง`,
              { text: currencyFormat(roomCost), alignment: "right" },
            ],

            ...data?.amenities.map((a) => [
              `สิ่งอำนวยความสะดวก: ${a.name}`,
              "-",
              {
                // text: currencyFormat(
                //   Number(a.price || 0) + Number(a.deposit || 0)
                // ),
                text: currencyFormat(Number(a.price || 0)),
                alignment: "right",
              },
            ]),

            ...data?.food_and_drinks.map((f) => [
              `อาหาร/เครื่องดื่ม: ${f.name} (ต่อชุด ${currencyFormat(
                f.price
              )})`,
              `${data?.number_attendees} ชุด`,
              {
                text: currencyFormat(
                  Number(f.price || 0) * Number(data?.number_attendees || 0)
                ),
                alignment: "right",
              },
            ]),
            // Subtotal row (optional but good for clarity)
            [
              {
                text: "รวมยอดก่อนหักส่วนลด",
                colSpan: 2,
                alignment: "right",
                bold: true,
              },
              {},
              {
                text: currencyFormat(totalCost),
                alignment: "right",
                bold: true,
              },
            ],
            // Discount row
            [
              {
                text: `ส่วนลด (${discountPercentage}%)`,
                colSpan: 2,
                alignment: "right",
              },
              {},
              {
                text: `- ${currencyFormat(discountAmount)}`,
                alignment: "right",
                color: "#ff0000",
              },
            ],
            // Final total row
            [
              {
                text: `ค่ามัดจำห้อง`,
                colSpan: 2,
                alignment: "right",
              },
              {},
              {
                text: `- ${currencyFormat(deposit)}`,
                alignment: "right",
                color: "#ff0000",
              },
            ],
            [
              {
                text: "ยอดรวมสุทธิ",
                colSpan: 2,
                alignment: "right",
                bold: true,
              },
              {},
              {
                text: currencyFormat(finalTotalCost - deposit),
                bold: true,
                alignment: "right",
              },
            ],
          ],
        },
        layout: "lightHorizontalLines",
        margin: [0, 10],
      },

      {
        text: "หมายเหตุ: ชำระค่ามัดจำและส่งสลิปทาง Line Official TENX ส่วนยอดที่เหลือชำระหน้าเคาน์เตอร์ในวันที่ใช้ห้องประชุม",
        italics: true,
        margin: [0, 10, 0, 0],
      },
    ],
    defaultStyle: { font: "THSarabunNew" },
    styles: {
      header: {
        fontSize: 18,
        bold: true,
      },
    },
  };
  return docDefinition;
};
