// BookingRoomModal.jsx
import React, { useEffect, useMemo, useState } from "react";
import {
  Modal,
  Form,
  Input,
  InputNumber,
  Select,
  DatePicker,
  TimePicker,
  Row,
  Col,
  Divider,
  Alert,
  Checkbox,
  Typography,
  Button,
  notification,
  Space,
} from "antd";
import { CoffeeOutlined } from "@ant-design/icons";
import baseAPI from "../api/baseAPI";
import dayjs from "dayjs";
// Import the new FoodAndDrinksModal component
import FoodAndDrinksModal from "./FoodAndDrinksModal"; // Import allFoodAndDrinksData ด้วย
import { useSelector } from "react-redux";

const { Title, Text } = Typography;

// 1. ⚙️ ฟังก์ชันคำนวณราคารวมค่าเช่าห้องประชุม (Room Rental Cost)
/**
 * คำนวณราคารวมค่าเช่าห้องประชุมตามชั่วโมงที่จอง
 * @param {object} room - ข้อมูลห้องประชุม {price: "500.00", hours: 2, next_hour_price: "100.00"}
 * @param {number} bookingHours - จำนวนชั่วโมงที่จองจริง
 * @returns {number} ราคารวมค่าเช่า
 */
const calculateTotalPrice = (room, bookingHours) => {
  // ต้องตรวจสอบ room.price, room.hours, และ room.next_hour_price ว่ามีค่าหรือไม่
  if (!room || !room.price || !room.hours || !room.next_hour_price) {
    return 0;
  }

  // แปลงค่าให้เป็นตัวเลขทศนิยม
  const basePrice = parseFloat(room.price);
  const baseHours = parseInt(room.hours);
  const nextHourPrice = parseFloat(room.next_hour_price);

  if (bookingHours <= 0 || isNaN(bookingHours)) {
    return 0;
  }

  // 1. ถ้าชั่วโมงที่จองน้อยกว่าหรือเท่ากับชั่วโมงพื้นฐาน
  if (bookingHours <= baseHours) {
    return basePrice;
  }

  // 2. ถ้าชั่วโมงที่จองมากกว่าชั่วโมงพื้นฐาน
  const extraHours = bookingHours - baseHours;
  const extraPrice = extraHours * nextHourPrice;

  const totalPrice = basePrice + extraPrice;

  // จำกัดให้แสดงทศนิยม 2 ตำแหน่ง
  return parseFloat(totalPrice.toFixed(2));
};

export default function BookingRoomModal({
  open,
  onClose,
  onFinish,
  room,
  // selectedRoomId,
  // roomPrice = 0,
}) {
  const allAmenitiesData = useSelector((state) => state.amenities);

  const groupedAllAmenities = {};
  allAmenitiesData.forEach((amenity) => {
    if (!groupedAllAmenities[amenity.category]) {
      groupedAllAmenities[amenity.category] = [];
    }
    groupedAllAmenities[amenity.category].push({
      label: amenity.name,
      value: amenity.name,
    });
  });

  const categoryOrder = ["Display", "Sound", "Video Conferencing", "Other"];

  const [form] = Form.useForm();
  const [rooms, setRooms] = useState([]);
  const [bookingError, setBookingError] = useState(null);
  const [isFoodModalOpen, setIsFoodModalOpen] = useState(false);
  const [selectedFoodAndDrinks, setSelectedFoodAndDrinks] = useState([]);
  const [bookingHours, setBookingHours] = useState(0);
  const [roomRentalCost, setRoomRentalCost] = useState(0); // 👈 เพิ่ม State ใหม่สำหรับค่าห้องประชุมที่คำนวณ
  const [amenitiesCost, setAmenitiesCost] = useState(0);
  const [foodCost, setFoodCost] = useState(0);
  const [totalCost, setTotalCost] = useState(0);
  const [promotionCode, setPromotionCode] = useState("");
  const [promotion, setPromotion] = useState(null);
  const [codeCheck, setCodeCheck] = useState(false);
  const [codeExpire, setCodeExpire] = useState(false);
  const [endTimeDisplay, setEndTimeDisplay] = useState(null); // 👈 เพิ่ม state สำหรับเวลาสิ้นสุด
  // const [promotionText, setPromotionText] = useState("");
  // const [endTimeHourOptions, setEndTimeHourOptions] = useState([]);

  const watchStartTime = Form.useWatch("start_time", form);
  const watchEndTime = Form.useWatch("end_time", form);
  const watchAmenities = Form.useWatch("amenities", form);
  const watchAttendees = Form.useWatch("number_attendees", form); // 👈 เพิ่ม Watcher สำหรับจำนวนคน

  const allFoodAndDrinksData = useSelector((state) => state.foodAndDrinks);

  // กำหนดเวลาเปิด/ปิด และเวลาพักเที่ยง
  // กำหนดค่าคงที่ (อ้างอิงจากโค้ดเดิม)
  const OPEN_TIME = "08:00";
  const CLOSE_TIME = "17:00"; // เวลาปิดทำการ
  const LUNCH_START = "12:00";
  const LUNCH_END = "13:00";
  const LUNCH_DURATION_MINUTES = 60; // 1 ชั่วโมง
  const FULL_DAY_BOOKING_HOURS = 8; // การจองเต็มวันคือ 8 ชั่วโมง
  const MIN_BOOKING_HOURS = room?.hours || 1;

  useEffect(() => {
    fethMeetingRooms();
  }, []);

  useEffect(() => {
    if (open && room?.id) {
      form.setFieldsValue({
        room_id: room.id,
        amenities: [],
        // ไม่ต้อง set food_and_drinks ที่นี่แล้ว เพราะ FoodAndDrinksModal จะจัดการเอง
      });
      setSelectedFoodAndDrinks([]); // Clear selected food/drinks when main modal opens
    } else if (!open) {
      // เมื่อ BookingRoomModal ปิด ให้ reset form และ clear selected food/drinks
      form.resetFields();
      setSelectedFoodAndDrinks([]);
      setBookingError(null);
    }
  }, [open, room.id, form]);

  const fethMeetingRooms = async () => {
    try {
      const result = await baseAPI.get(`/meetingrooms`);
      setRooms(result.data);
    } catch (error) {
      console.error("Failed to fetch rooms:", error);
      notification.error({
        message: "เกิดข้อผิดพลาด",
        description: "ไม่สามารถดึงข้อมูลห้องประชุมได้",
      });
    }
  };

  const onSubmit = async (data) => {
    try {
      const res = await baseAPI.post(`/booking-rooms`, data);

      if (res.status === 201) {
        setBookingError("");
        // ไม่ต้อง resetFields หรือ clear selectedFoodAndDrinks ที่นี่
        // เพราะ useEffect ด้านบนจะจัดการเมื่อ Modal ปิด
        // notification.success({
        //   message: "จองห้องประชุมสำเร็จ",
        //   description: "เจ้าหน้าที่จะติดต่อกลับไปยืนยันการจองของคุณ",
        // });
        onFinish(data); // Call onFinish of parent (RoomDetailsPage) which also closes this modal
      } else if (res.status === 200) {
        const errorMessage =
          res.data?.message ||
          "ขออภัยวันและเวลาดังกล่าวถูกจองแล้ว กรุณาเลือกเวลาอื่น ";
        setBookingError(errorMessage);
      }
    } catch (err) {
      console.error("Booking Error:", err);
      const backendErrorMessage =
        err.response?.data?.message ||
        "ไม่สามารถทำรายการจองได้ กรุณาลองใหม่อีกครั้ง";
      notification.error({
        message: "เกิดข้อผิดพลาด",
        description: backendErrorMessage,
      });
      setBookingError(backendErrorMessage);
    }
  };

  const handleSubmit = (values) => {
    const formattedDate = values.date ? values.date.format("YYYY-MM-DD") : null;
    const formattedStartTime = values.start_time
      ? values.start_time.format("HH:mm") + ":00"
      : null;
    const formattedEndTime = endTimeDisplay
      ? dayjs(endTimeDisplay, "HH:mm").format("HH:mm:ss")
      : null;

    const submitData = {
      ...room,
      ...values,
      promotion_id: promotion?.id || null,
      discount: promotion?.discount || 0,
      date: formattedDate,
      start_time: formattedStartTime,
      end_time: formattedEndTime,
      amenities: (values.amenities || [])
        .map((name) => allAmenitiesData.find((a) => a.name === name))
        .filter(Boolean),
      // Use selectedFoodAndDrinks from state
      food_and_drinks: selectedFoodAndDrinks
        .map((name) => {
          // Find the full item object from allFoodAndDrinksData
          return allFoodAndDrinksData.find((item) => item.name === name);
        })
        .filter(Boolean),
    };

    // console.log("Submit", submitData);
    // alert("ระบบยังไม่สมบูรณ์เป็นเพียงตัวอย่างเท่านั้น");

    onSubmit(submitData);
  };

  const handleFinishFailed = (errorInfo) => {
    // console.log("Failed:", errorInfo);
    notification.info({
      message: "กรุณากรอกข้อมูลในส่วนที่บังคับกรอก ให้ครบ!",
      description: errorInfo,
      // placement: "bottomRight",
      duration: 2,
    });
  };

  const handleCancel = () => {
    // การ resetFields และ clear selectedFoodAndDrinks ถูกย้ายไปที่ useEffect เมื่อ open เป็น false
    onClose(false);
  };

  const handleCheckPromotionCode = async () => {
    const result = await baseAPI.get(`/promotions`, {
      params: { code: promotionCode },
    });
    console.log(result.data);
    if (
      dayjs().format("YYYY-MM-DD") >
        dayjs(result.data.end_date).format("YYYY-MM-DD") ||
      result.data.booking_count >= result.data.number_of_rights
    ) {
      console.log("TRUE");
      setCodeExpire(true);
      setCodeCheck(false);
    } else {
      console.log("FALSE");
      setCodeCheck(true);
      setCodeExpire(false);
    }

    setPromotion(result.data);
  };

  // --- Food/Drinks Modal Handlers ---
  const handleOpenFoodModal = () => {
    setIsFoodModalOpen(true);
    // ไม่ต้อง setFieldsValue ที่นี่แล้ว เพราะ FoodAndDrinksModal จะใช้ initialSelectedItems
  };

  const handleCloseFoodModal = () => {
    setIsFoodModalOpen(false);
  };

  // Callback function to receive selected food/drinks from FoodAndDrinksModal
  const handleSaveFoodAndDrinks = (items) => {
    setSelectedFoodAndDrinks(items); // Update the state in BookingRoomModal
    notification.info({
      message: "รายการอาหาร/เครื่องดื่มถูกบันทึกแล้ว",
      description: `เลือกไป ${items.length} รายการ`,
      duration: 3,
    });
  };

  const calculateRemainingHours = (startTime) => {
    if (!startTime) return 0;

    const startMoment = dayjs(startTime, "HH:mm");
    const closeMoment = dayjs(CLOSE_TIME, "HH:mm");
    const lunchStartMoment = dayjs(LUNCH_START, "HH:mm");
    const lunchEndMoment = dayjs(LUNCH_END, "HH:mm");
    const lunchDurationMinutes = lunchEndMoment.diff(
      lunchStartMoment,
      "minute"
    ); // 60 นาที

    // คำนวณความต่างเวลารวมทั้งหมดเป็นนาที
    let totalDiffMinutes = closeMoment.diff(startMoment, "minute");

    // ถ้าเวลาเริ่มต้นอยู่ก่อนเวลาพักเที่ยง (12:00)
    if (startMoment.isBefore(lunchStartMoment)) {
      // และเวลาสิ้นสุดรวม (17:00) อยู่หลังเวลาพักเที่ยง
      if (closeMoment.isAfter(lunchStartMoment)) {
        // หักช่วงพักเที่ยงออก
        totalDiffMinutes -= lunchDurationMinutes;
      }
    }
    // ถ้าเวลาเริ่มต้นอยู่ระหว่างเวลาพักเที่ยง (เป็นไปไม่ได้หากใช้ TimePicker disabledHours)
    // หรืออยู่หลังเวลาพักเที่ยง ไม่ต้องหักเพิ่ม

    // แปลงนาทีเป็นชั่วโมง และปัดลงให้เป็นจำนวนเต็มชั่วโมง
    const remainingHours = Math.floor(totalDiffMinutes / 60);

    return Math.max(remainingHours, 0); // ไม่ให้มีค่าติดลบ
  };

  // 2. ฟังก์ชันสร้างตัวเลือกจำนวนชั่วโมง
  const generateEndTimeOptions = (remainingHours) => {
    const options = [];
    // เริ่มต้นจากขั้นต่ำ 2 ชั่วโมง จนถึงจำนวนชั่วโมงที่เหลือ
    for (let h = MIN_BOOKING_HOURS; h <= remainingHours; h++) {
      options.push({
        label: `${h} ชั่วโมง ${h === 2 ? "(ขั้นต่ำ)" : ""}`,
        value: h.toString(), // ใช้ค่าเป็น string หรือ number ก็ได้ ตามที่ form.setFieldsValue ต้องการ
      });
    }
    return options;
  };

  // สร้าง options สำหรับ Select โดยใช้ useMemo เพื่อประสิทธิภาพ
  const endTimeHourOptions = useMemo(() => {
    // ใช้ watchStartTime ที่มาจาก dayjs object หรือ string/moment ตามที่ TimePicker ส่งมา
    const startTimeValue = watchStartTime
      ? watchStartTime.format("HH:mm")
      : null;
    const remainingHours = calculateRemainingHours(startTimeValue);
    return generateEndTimeOptions(remainingHours);
  }, [watchStartTime]);

  // 3. useEffect สำหรับคำนวณชั่วโมงจริงและ setBookingHours
  useEffect(() => {
    if (watchStartTime && watchEndTime) {
      const bookingDurationHours = parseFloat(watchEndTime);
      if (isNaN(bookingDurationHours) || bookingDurationHours === 0) {
        setBookingHours(0);
        setEndTimeDisplay(null);
        return;
      }

      const start = dayjs(watchStartTime.format("HH:mm"), "HH:mm");

      // 1. คำนวณเวลาสิ้นสุด 'แบบพื้นฐาน'
      let currentEnd = start.add(bookingDurationHours, "hour");

      const lunchStart = dayjs(LUNCH_START, "HH:mm");
      const lunchEnd = dayjs(LUNCH_END, "HH:mm");

      // 🛑 ตรรกะการปรับเวลาสิ้นสุด
      const isFullDayBooking = bookingDurationHours === FULL_DAY_BOOKING_HOURS;
      const isBookingOverlappingLunch =
        start.isBefore(lunchEnd) && currentEnd.isAfter(lunchStart);

      if (isBookingOverlappingLunch) {
        if (isFullDayBooking) {
          // กรณีจองเต็มวัน (8 ชม.): 'ไม่ต้องนับเที่ยง'
          currentEnd = currentEnd.add(LUNCH_DURATION_MINUTES, "minute");
        }
        // else: กรณีจองต่ำกว่า 8 ชั่วโมง: 'นับเที่ยง' ไม่ต้องบวกเพิ่ม
      }

      // ----------------------------------------------------------------
      // 2. การกำหนดค่า BOOKING HOURS ตามเงื่อนไขใหม่
      let calculatedHours;
      let finalEndTimeDisplay;

      if (isFullDayBooking) {
        calculatedHours = FULL_DAY_BOOKING_HOURS;
        const closeMoment = dayjs(CLOSE_TIME, "HH:mm");
        finalEndTimeDisplay = currentEnd.isAfter(closeMoment)
          ? closeMoment.format("HH:mm")
          : currentEnd.format("HH:mm");
      } else {
        const diff = currentEnd.diff(start, "minute") / 60;
        // ใช้ Math.ceil แทน Math.round หากต้องการปัดขึ้น 30 นาที เป็น 1 ชั่วโมง (ปกติใช้ round)
        calculatedHours = Math.max(Math.round(diff * 2) / 2, 0);
        finalEndTimeDisplay = currentEnd.format("HH:mm");
      }

      setBookingHours(calculatedHours);
      setEndTimeDisplay(finalEndTimeDisplay);
    } else {
      setBookingHours(0);
      setEndTimeDisplay(null);
    }
  }, [watchStartTime, watchEndTime]);

  // 4. 💰 useEffect ใหม่: คำนวณค่าเช่าห้องประชุม (Room Rental Cost)
  useEffect(() => {
    // ใช้ฟังก์ชัน calculateTotalPrice ที่ซับซ้อน
    const roomCost = calculateTotalPrice(room, bookingHours);
    setRoomRentalCost(roomCost);
  }, [room, bookingHours]); // อัปเดตเมื่อ room หรือ bookingHours เปลี่ยน

  // 5. 💰 useEffect เดิม: คำนวณราคาทั้งหมด (Total Cost)
  // แก้ไขให้ใช้ roomRentalCost แทน bookingHours * ~~room.price
  useEffect(() => {
    // 💰 รวมราคาทั้งหมด
    // 1. ค่าห้องประชุม: roomRentalCost
    // 2. ค่าสิ่งอำนวยความสะดวก: amenitiesCost
    // 3. ค่าอาหารรวม: foodCost (ต่อคน) * watchAttendees (จำนวนคน)
    const totalFoodCost = foodCost * (watchAttendees || 0);

    const calculatedTotalCost = roomRentalCost + amenitiesCost + totalFoodCost;

    setTotalCost(calculatedTotalCost);
  }, [roomRentalCost, amenitiesCost, foodCost, watchAttendees]); // เพิ่ม roomRentalCost และ watchAttendees ใน Dependency Array

  useEffect(() => {
    // 💡 คำนวณราคาสิ่งอำนวยความสะดวก
    const cost = (watchAmenities || []).reduce((sum, name) => {
      const item = allAmenitiesData.find((a) => a.name === name);
      // return (
      //   sum + (item && ~~item.price > 0 ? ~~item.price + ~~item.deposit : 0)
      // );
      return sum + (item && ~~item.price > 0 ? ~~item.price : 0);
    }, 0);
    setAmenitiesCost(cost);
  }, [watchAmenities]);

  useEffect(() => {
    // 🍴 คำนวณอาหาร/เครื่องดื่ม
    const cost = selectedFoodAndDrinks.reduce((sum, name) => {
      const item = allFoodAndDrinksData.find((d) => d.name === name);
      return sum + (item ? ~~item.price : 0);
    }, 0);
    setFoodCost(cost);
    console.log("COST", cost);
  }, [selectedFoodAndDrinks]);

  const handleChangePromotion = (e) => {
    // console.log(e);
    setCodeExpire(false);
    setPromotion(null);
    const value = e.target.value;
    setCodeCheck(false);
    value ? setPromotionCode(value.toUpperCase()) : setPromotionCode("");
  };

  const disabledTimeRange = () => {
    // สร้างอาร์เรย์ 0 ถึง 23
    const allHours = Array.from({ length: 24 }, (_, i) => i);

    // ชั่วโมงที่ต้องการปิดใช้งาน: 0-7 (ก่อน 8:00) และ 16-23 (หลัง 15:00)
    const disabled = allHours.filter((hour) => hour < 8 || hour > 15);

    return {
      // ฟังก์ชันนี้จะส่งคืนชั่วโมงที่ถูก disable
      disabledHours: () => disabled,

      // **หมายเหตุ:** ถ้าต้องการให้เลือกได้เฉพาะ 8:00 และ 15:00
      // โดยไม่มีนาทีอื่นแทรก เช่น ห้ามเลือก 15:01
      // คุณอาจต้องใช้ disabledMinutes ควบคู่ไปด้วย
    };
  };

  return (
    <div>
      <Modal
        title={`จองห้องประชุม`}
        open={open}
        onOk={form.submit}
        onCancel={handleCancel}
        cancelText="ยกเลิก"
        okText="จองห้องประชุม"
        destroyOnClose={false} // ตั้งเป็น false เพื่อให้ useEffect จัดการ resetFields
        width={700}
      >
        <Divider />
        <Form
          layout="vertical"
          form={form}
          onFinish={handleSubmit}
          onFinishFailed={handleFinishFailed}
          initialValues={{
            amenities: [],
            // ไม่ต้องมี food_and_drinks ที่นี่แล้ว เพราะจัดการที่ state และส่งไป FoodAndDrinksModal
          }}
        >
          {room?.id ? (
            <Form.Item label="ห้องประชุมที่เลือก">
              <Input
                value={
                  rooms.find((r) => r.id === room?.id)?.title || "กำลังโหลด..."
                }
                readOnly
              />
              <Form.Item name="room_id" hidden initialValue={room?.id}>
                <Input />
              </Form.Item>
            </Form.Item>
          ) : (
            <Form.Item
              name="room_id"
              label="เลือกห้องประชุม"
              rules={[{ required: true, message: "กรุณาเลือกห้องประชุม!" }]}
            >
              <Select
                placeholder="เลือกห้องประชุมที่ต้องการ"
                options={rooms.map((item) => ({
                  value: item.id,
                  label: `${item.title} (รองรับ ${item.capacity} ที่นั่ง)`,
                }))}
              />
            </Form.Item>
          )}

          <Form.Item
            name="booked_by"
            label="ชื่อผู้จอง หรือชื่อหน่วยงาน"
            rules={[
              { required: true, message: "กรุณากรอกชื่อผู้จองหรือหน่วยงาน!" },
            ]}
          >
            <Input />
          </Form.Item>

          <Form.Item
            name="phone"
            label="เบอร์โทรศัพท์"
            rules={[{ required: true, message: "กรุณากรอกเบอร์โทรศัพท์!" }]}
          >
            <Input />
          </Form.Item>

          <Form.Item
            name="email"
            label="Email"
            rules={[{ type: "email", message: "รูปแบบอีเมลไม่ถูกต้อง!" }]}
          >
            <Input />
          </Form.Item>

          <Form.Item
            name="number_attendees"
            label="จำนวนผู้เข้าร่วม"
            rules={[{ required: true, message: "กรุณากรอกจำนวนผู้เข้าร่วม!" }]}
          >
            <InputNumber min={1} style={{ width: "100%" }} />
          </Form.Item>

          <Row gutter={16}>
            <Col xs={24} sm={8}>
              <Form.Item
                name="date"
                label="จองวันที่"
                rules={[{ required: true, message: "กรุณาเลือกวันที่!" }]}
              >
                <DatePicker style={{ width: "100%" }} format="YYYY-MM-DD" />
              </Form.Item>
            </Col>
            <Col xs={24} sm={8}>
              <Form.Item
                name="start_time"
                label="เริ่มเวลา"
                rules={[{ required: true, message: "กรุณาเลือกเวลาเริ่มต้น!" }]}
              >
                <TimePicker
                  // ใช้ disabledTime สำหรับกำหนดเวลาที่ไม่สามารถเลือกได้
                  disabledTime={disabledTimeRange}
                  style={{ width: "100%" }}
                  format="HH:mm"
                  minuteStep={30}
                />
              </Form.Item>
            </Col>
            <Col xs={24} sm={8}>
              <Form.Item
                name="end_time"
                label="จำนวนชั่วโมง"
                rules={[{ required: true, message: "กรุณาเลือกเวลาเริ่มต้น!" }]}
              >
                <Select
                  // onChange={handleChangeEndTime}
                  options={endTimeHourOptions}
                ></Select>
              </Form.Item>
            </Col>
            <Col xs={24}>
              <p>
                ชั่วโมงที่ถูกคำนวณ : **{form.getFieldValue("end_time")}{" "}
                ชั่วโมง** {/* 👈 แสดงผลระยะเวลาสิ้นสุด */}
                {endTimeDisplay && ` (สิ้นสุดเวลา ${endTimeDisplay} น.)`}
              </p>
            </Col>
          </Row>

          <Form.Item name="purpose" label="วัตถุประสงค์ / ความคิดเห็นเพิ่มเติม">
            <Input.TextArea rows={2} />
          </Form.Item>

          <Divider orientation="left">
            <Title level={5}>เลือกสิ่งอำนวยความสะดวกเพิ่มเติม</Title>
          </Divider>

          <Form.Item name="amenities">
            <Checkbox.Group style={{ width: "100%" }}>
              <div style={{ display: "flex", flexDirection: "column" }}>
                {categoryOrder.map((category) => {
                  const amenitiesInThisCategory = groupedAllAmenities[category];
                  if (
                    amenitiesInThisCategory &&
                    amenitiesInThisCategory.length > 0
                  ) {
                    return (
                      <div
                      // key={category}
                      // style={{
                      //   padding: 16,
                      //   border: "1px solid #f0f0f0",
                      //   borderRadius: 8,
                      // }}
                      >
                        <Title level={5} style={{ marginBottom: 8 }}>
                          {category}
                        </Title>
                        <Row gutter={[32, 32]}>
                          {amenitiesInThisCategory.map((option) => {
                            const fullItem = allAmenitiesData.find(
                              (a) => a.name === option.label
                            );
                            const isPaid = fullItem && !fullItem.is_free;
                            return (
                              <Col key={option.value} xs={24} sm={12} md={8}>
                                <Checkbox value={option.value}>
                                  <div
                                    style={{
                                      display: "flex",
                                      flexDirection: "column",
                                    }}
                                  >
                                    <span>{option.label} </span>

                                    <span
                                      style={{
                                        fontSize: "12px",
                                        color:
                                          fullItem.price > 0
                                            ? "#fa541c"
                                            : "#52c41a",
                                      }}
                                    >
                                      {fullItem.price > 0
                                        ? `+฿${fullItem.price}`
                                        : "ฟรี"}
                                    </span>
                                    <Text
                                      style={{ fontSize: 12 }}
                                      type="secondary"
                                    >
                                      {/* {fullItem.deposit > 0
                                        ? "(+ค่ามัดจำ " + fullItem.deposit + ")"
                                        : ""} */}
                                    </Text>
                                  </div>
                                </Checkbox>
                              </Col>
                            );
                          })}
                        </Row>
                      </div>
                    );
                  }
                  return null;
                })}
              </div>
            </Checkbox.Group>
          </Form.Item>

          {/* --- Integrate FoodAndDrinksModal --- */}
          {/* <Divider orientation="left">
            <Title level={5}>บริการอาหารและเครื่องดื่ม</Title>
          </Divider>
          <Form.Item label="ค่าอาหารคิดตามจำนวนที่นั่งต่อหนึ่งรายการ">
            <Button
              type="dashed"
              icon={<CoffeeOutlined />}
              onClick={handleOpenFoodModal}
              block
              style={{ height: "auto", padding: "10px 15px" }}
            >
              {selectedFoodAndDrinks.length > 0 ? (
                <div style={{ textAlign: "left" }}>
                  <Text strong>
                    เลือกแล้ว {selectedFoodAndDrinks.length} รายการ:
                  </Text>
                  <br />
                  <Text
                    type="secondary"
                    style={{ whiteSpace: "normal", display: "block" }}
                  >
                    {selectedFoodAndDrinks
                      .map(
                        (name) =>
                          allFoodAndDrinksData.find(
                            (item) => item.name === name
                          )?.name || name
                      )
                      .join(", ")}
                  </Text>
                </div>
              ) : (
                "เพิ่มรายการอาหารหรือเครื่องดื่ม"
              )}
            </Button>
            {selectedFoodAndDrinks.length > 0 && (
              <Text
                type="secondary"
                style={{ marginTop: "8px", display: "block" }}
              >
                รวมราคาอาหาร, เครื่องดื่ม /
                {form.getFieldValue("number_attendees")} ที่นั่ง: THB{" "}
                {selectedFoodAndDrinks.reduce((sum, name) => {
                  const item = allFoodAndDrinksData.find(
                    (d) => d.name === name
                  );
                  return (
                    sum +
                    (item
                      ? item.price *
                        Number(form.getFieldValue("number_attendees"))
                      : 0)
                  );
                }, 0)}
              </Text>
            )}
          </Form.Item> */}
          <Divider />
          <div style={{ width: "100%", marginBottom: 16 }}>
            <Space>
              <Text>PROMOTION CODE (ถ้ามี)</Text>
              <Input onChange={handleChangePromotion} />
              <Button
                type="dashed"
                disabled={!promotionCode}
                onClick={handleCheckPromotionCode}
              >
                ตรวจสอบ
              </Button>
            </Space>
          </div>
          {promotion && codeCheck && !codeExpire ? (
            <Text style={{ color: "green" }}>
              ได้รับโปรโมชั่น/ส่วนลด: {promotion?.discount}% คำอธิบาย:{" "}
              {promotion?.description}
            </Text>
          ) : codeExpire ? (
            <Text type="danger">
              โค้ดส่วนลดนี้หมดอายุ หรือใช้สิทธิ์ครบที่กำหนดแล้ว
            </Text>
          ) : (
            codeCheck && <Text>ไม่พบโปรโมชั่นสำหรับ CODE นี้</Text>
          )}

          <Divider orientation="left">
            <Title level={5}>สรุปการจอง</Title>
          </Divider>

          <Row gutter={[16, 8]}>
            <Col span={12}>
              {" "}
              <Text strong>จำนวนชั่วโมง:</Text>{" "}
            </Col>
            <Col span={12} style={{ textAlign: "right" }}>
              {" "}
              <Text>{bookingHours.toFixed(2)} ชั่วโมง</Text>
            </Col>

            {/* 6. ✅ แก้ไข: ค่าบริการห้องประชุม (ใช้ roomRentalCost ที่คำนวณจาก calculateTotalPrice) */}
            <Col span={12}>
              <Text strong>ค่าบริการห้องประชุม:</Text>{" "}
            </Col>
            <Col span={12} style={{ textAlign: "right" }}>
              <Text>
                THB{" "}
                {roomRentalCost.toLocaleString("th-TH", {
                  minimumFractionDigits: 2,
                })}
              </Text>
            </Col>

            <Col span={12}>
              <Text strong>ค่าบริการสิ่งอำนวยความสะดวก:</Text>{" "}
            </Col>
            <Col span={12} style={{ textAlign: "right" }}>
              <Text>
                THB{" "}
                {amenitiesCost.toLocaleString("th-TH", {
                  minimumFractionDigits: 2,
                })}
              </Text>
            </Col>

            <Col span={12}>
              <Text strong>ค่าอาหาร/เครื่องดื่ม:</Text>{" "}
            </Col>
            <Col span={12} style={{ textAlign: "right" }}>
              <Text>
                THB{" "}
                {(foodCost * (watchAttendees || 0)).toLocaleString("th-TH", {
                  minimumFractionDigits: 2,
                })}
              </Text>
            </Col>

            <Col span={12}>
              <Text strong>โปรโมชั่น/ส่วนลด:</Text>{" "}
            </Col>
            <Col span={12} style={{ textAlign: "right" }}>
              {promotion ? (
                // คำนวณส่วนลดจาก totalCost (ยอดรวมก่อนหักส่วนลด)
                <Text type="danger">
                  -THB{" "}
                  {((promotion?.discount * totalCost) / 100).toLocaleString(
                    "th-TH",
                    { minimumFractionDigits: 2 }
                  )}
                </Text>
              ) : (
                <Text>-THB 0.00</Text>
              )}
            </Col>

            {/* รวมทั้งสิ้น */}
            <Col span={12}>
              <Text strong>รวมทั้งสิ้น:</Text>{" "}
            </Col>
            <Col span={12} style={{ textAlign: "right" }}>
              <Text type="danger" strong style={{ fontSize: "18px" }}>
                THB{" "}
                {(
                  totalCost -
                  (totalCost * (promotion?.discount || 0)) / 100
                ).toLocaleString("th-TH", { minimumFractionDigits: 2 })}
              </Text>
            </Col>
          </Row>
          <Divider />
          {/* <Form.Item name="promotion_code" label="Promotion code (ถ้ามี)">
            <Input />
          </Form.Item> */}
        </Form>

        {/* <Divider /> */}
        {bookingError && (
          <Alert
            message={bookingError}
            type="error"
            showIcon
            style={{ marginTop: 16 }}
          />
        )}
      </Modal>

      {/* --- Render the new FoodAndDrinksModal component --- */}
      <FoodAndDrinksModal
        open={isFoodModalOpen}
        onClose={handleCloseFoodModal}
        onSave={handleSaveFoodAndDrinks} // Pass the callback function
        initialSelectedItems={selectedFoodAndDrinks} // Pass current selected items
      />
    </div>
  );
}
